const body = $input.first().json.body ?? {};
if (body.source !== 'web' || typeof body.email !== 'string' || body.email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) throw new Error('Solicitud inválida');
return [{json:{email:body.email.trim().toLowerCase()}}];

const email = $('Validar correo').first().json.email;
const normalize = value => String(value ?? '').trim().toLowerCase();
const yes = value => normalize(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '') === 'si';
const rows = $input.all().map(item => item.json);
if (rows.some(row => row.row_number != null) && !rows.some(row => Object.hasOwn(row, 'email') && Object.hasOwn(row, 'web_profile') && Object.hasOwn(row, 'web_enabled'))) throw new Error('Faltan columnas web');
const matches = rows.filter(row => normalize(row.email) === email);
if (matches.length > 1) throw new Error('Correo duplicado');
const row = matches[0];
if (!row || !yes(row.web_enabled) || !['devAdmin','Labruna'].includes(String(row.web_profile ?? '').trim())) return [{json:{authorized:false}}];
const allowedModules = ['remitos','chapas','cheques'].filter(module => yes(row['auth_' + module]));
return [{json:{authorized:true,user:{name:String(row.name ?? '').trim() || String(row.web_profile).trim(),email,profile:String(row.web_profile).trim(),allowedModules}}}];
